            db    $FF,$37,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_DUNGEON4_MATCH
            db    $30,$00,$12,$16,$27,$36,$08,$18,$28,$12,$18,$28   ; BG0-BG3
            db    $FF,$27,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_DUNGEON5_MATCH
            db    $30,$00,$12,$16,$27,$36,$0A,$1A,$2A,$16,$1A,$2A   ; BG0-BG3
            db    $FF,$27,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_DUNGEON6_MATCH
