            db    $FF,$27,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_DUNGEON7_MATCH
            db    $30,$00,$12,$16,$27,$36,$0A,$1A,$2A,$12,$1A,$2A   ; BG0-BG3
            db    $FF,$27,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_DUNGEON8_MATCH
            db    $30,$00,$12,$16,$27,$36,$00,$10,$30,$22,$10,$30   ; BG0-BG3
            db    $FF,$27,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3
PAL_DUNGEON9_MATCH
            db    $30,$00,$12,$16,$27,$36,$00,$10,$30,$16,$10,$30   ; BG0-BG3
            db    $FF,$27,$17,$02,$22,$30,$16,$27,$30,$FF,$FF,$FF   ; SP0-SP3

